{
  "decision-export-corrected-appliance-inventory": "WITH ranked AS (SELECT asset_id, label_text, rated_w, ROW_NUMBER() OVER (PARTITION BY asset_id ORDER BY revision_no DESC) AS rn FROM asset_revision) SELECT 'asset_id,label,rated_w' || char(10) || COALESCE(group_concat(line, ''), '') AS csv_text FROM (SELECT asset_id || ',\"' || replace(label_text, '\"', '\"\"') || '\",' || rated_w || char(10) AS line FROM ranked WHERE rn = 1 AND rated_w IS NOT NULL ORDER BY asset_id COLLATE BINARY)",
  "decision-export-evidence-backed-accrual-adjustments": "WITH ranked AS (SELECT work_code, source_id, measured_units, ROW_NUMBER() OVER (PARTITION BY work_code ORDER BY signed_on DESC, revision_no DESC) AS rn FROM field_certificate WHERE signed_on <= '2026-09-30'), adjustments AS (SELECT r.work_code, r.source_id, r.measured_units * a.rate_cents - a.booked_cents AS adjustment_cents FROM ranked AS r JOIN work_account AS a ON a.work_code = r.work_code WHERE r.rn = 1) SELECT 'work_code,source_id,adjustment_cents' || char(10) || COALESCE(group_concat(line, ''), '') AS csv_content FROM (SELECT '\"' || replace(work_code, '\"', '\"\"') || '\",\"' || replace(source_id, '\"', '\"\"') || '\",' || adjustment_cents || char(10) AS line FROM adjustments WHERE adjustment_cents <> 0 ORDER BY work_code COLLATE BINARY)",
  "decision-export-page-specific-caption-errata": "SELECT 'page,panel,caption,source_id' || char(10) || COALESCE(group_concat(line, ''), '') AS csv_body FROM (SELECT p.page_num || ',\"' || replace(p.panel_code, '\"', '\"\"') || '\",\"' || replace(c.intended_caption, '\"', '\"\"') || '\",\"' || replace(c.source_id, '\"', '\"\"') || '\"' || char(10) AS line FROM printed_panel AS p JOIN mount_card AS c ON c.page_num = p.page_num AND c.panel_code = p.panel_code COLLATE BINARY WHERE c.intended_caption IS NOT NULL AND c.intended_caption COLLATE BINARY <> p.printed_caption ORDER BY p.page_num, p.panel_code COLLATE BINARY)",
  "decision-export-paired-counter-exceptions": "WITH paired AS (SELECT burst_tag, MAX(CASE WHEN counter_kind = 'incumbent' THEN parcel_count END) AS incumbent, MAX(CASE WHEN counter_kind = 'shadow' THEN parcel_count END) AS shadow FROM counter_reports GROUP BY burst_tag COLLATE BINARY) SELECT 'burst,incumbent,shadow' || char(10) || COALESCE(group_concat(line, ''), '') AS csv_contents FROM (SELECT '\"' || replace(burst_tag, '\"', '\"\"') || '\",' || COALESCE(incumbent, '') || ',' || COALESCE(shadow, '') || char(10) AS line FROM paired WHERE incumbent IS NULL OR shadow IS NULL OR incumbent <> shadow ORDER BY burst_tag COLLATE BINARY)"
}
